// Builds web/styles/tokens.css from brand/tokens.json (the design system's tokens) and copies
// brand/components.css. Generated files are committed; tests/brand.test.ts fails if they drift.
import { readFileSync, writeFileSync } from "node:fs";

export function tokensCss(t) {
  const byName = new Map(t.color.tokens.map((c) => [c.name, c]));
  const resolve = (v) => (typeof v === "string" && v.startsWith("{") ? `var(--${v.slice(1, -1)})` : v);
  const colors = (theme) =>
    t.color.tokens.map((c) => `  --${c.name}: ${resolve(typeof c.value === "string" ? c.value : c.value[theme] ?? c.value.light)};`).join("\n");
  const flat = (fam) => (t[fam]?.tokens ?? []).map((x) => `  --${x.name}: ${x.value};`).join("\n");
  const fams = Object.entries(t.type.families).map(([k, v]) => `  --font-${k}: ${v};`).join("\n");
  const styles = t.type.groups
    .flatMap((g) => g.styles.map((s) => ({ ...s, family: s.family ?? g.family })))
    .map(
      (s) =>
        `.t-${s.name} { font-family: var(--font-${s.family}); font-size: ${s.fontSize}; line-height: ${s.lineHeight}; font-weight: ${s.fontWeight};${
          s.letterSpacing ? ` letter-spacing: ${s.letterSpacing};` : ""
        } }`,
    )
    .join("\n");
  void byName;
  return `/* Generated by scripts/build-tokens.mjs from brand/tokens.json. Do not edit. */
:root, [data-theme="light"] {
  color-scheme: light;
${colors("light")}
}
[data-theme="dark"] {
  color-scheme: dark;
${colors("dark")}
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
${colors("dark").replace(/^/gm, "  ")}
  }
}
:root {
${flat("spacing")}
${flat("radius")}
${flat("shadow")}
${fams}
}
${styles}
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const t = JSON.parse(readFileSync("brand/tokens.json", "utf8"));
  writeFileSync("web/styles/tokens.css", tokensCss(t));
  writeFileSync("web/styles/components.css", "/* Copied from brand/components.css by scripts/build-tokens.mjs. Do not edit here. */\n" + readFileSync("brand/components.css", "utf8"));
  console.log("web/styles/tokens.css, web/styles/components.css");
}
